-- Create users table\nCREATE TABLE public.users (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  email TEXT UNIQUE NOT NULL,\n  name TEXT NOT NULL,\n  role TEXT NOT NULL CHECK (role IN ('Teacher', 'Parent')),\n  child_name TEXT,\n  password_hash TEXT NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Create subjects table\nCREATE TABLE public.subjects (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  name TEXT NOT NULL,\n  teacher_id UUID NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Create exams table\nCREATE TABLE public.exams (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  subject_id UUID NOT NULL REFERENCES public.subjects(id) ON DELETE CASCADE,\n  title TEXT NOT NULL,\n  type TEXT NOT NULL CHECK (type IN ('Exam', 'Quiz')),\n  date DATE NOT NULL,\n  description TEXT,\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Create results table\nCREATE TABLE public.results (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  subject_id UUID NOT NULL REFERENCES public.subjects(id) ON DELETE CASCADE,\n  exam_id UUID REFERENCES public.exams(id) ON DELETE SET NULL,\n  student_name TEXT NOT NULL,\n  score INTEGER NOT NULL CHECK (score >= 0 AND score <= 100),\n  grade TEXT NOT NULL,\n  date DATE NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Create announcements table\nCREATE TABLE public.announcements (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  title TEXT NOT NULL,\n  message TEXT NOT NULL,\n  author_id UUID NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,\n  author TEXT NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Create chats table\nCREATE TABLE public.chats (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  sender_id UUID NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,\n  sender_name TEXT NOT NULL,\n  role TEXT NOT NULL CHECK (role IN ('Teacher', 'Parent')),\n  text TEXT NOT NULL,\n  timestamp TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Create indexes for better query performance\nCREATE INDEX idx_subjects_teacher_id ON public.subjects(teacher_id);\nCREATE INDEX idx_exams_subject_id ON public.exams(subject_id);\nCREATE INDEX idx_results_subject_id ON public.results(subject_id);\nCREATE INDEX idx_results_exam_id ON public.results(exam_id);\nCREATE INDEX idx_announcements_author_id ON public.announcements(author_id);\nCREATE INDEX idx_chats_sender_id ON public.chats(sender_id);\nCREATE INDEX idx_chats_timestamp ON public.chats(timestamp);\n\n-- Enable Row Level Security (RLS)\nALTER TABLE public.users ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.subjects ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.exams ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.results ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.announcements ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.chats ENABLE ROW LEVEL SECURITY;\n\n-- RLS Policies\n-- Users can view their own profile\nCREATE POLICY \"Users can view own profile\" ON public.users\n  FOR SELECT USING (auth.uid()::text = id::text);\n\n-- Anyone can view user names (for chat display)\nCREATE POLICY \"Anyone can view user names\" ON public.users\n  FOR SELECT USING (true);\n\n-- Teachers can view their own subjects\nCREATE POLICY \"Teachers can view own subjects\" ON public.subjects\n  FOR SELECT USING (teacher_id::text = auth.uid()::text);\n\n-- Teachers can insert subjects\nCREATE POLICY \"Teachers can insert subjects\" ON public.subjects\n  FOR INSERT WITH CHECK (teacher_id::text = auth.uid()::text);\n\n-- Teachers can update own subjects\nCREATE POLICY \"Teachers can update own subjects\" ON public.subjects\n  FOR UPDATE USING (teacher_id::text = auth.uid()::text);\n\n-- Teachers can delete own subjects\nCREATE POLICY \"Teachers can delete own subjects\" ON public.subjects\n  FOR DELETE USING (teacher_id::text = auth.uid()::text);\n\n-- Exams visible to teachers of that subject\nCREATE POLICY \"Teachers can view own exams\" ON public.exams\n  FOR SELECT USING (\n    subject_id IN (\n      SELECT id FROM public.subjects WHERE teacher_id::text = auth.uid()::text\n    )\n  );\n\n-- Teachers can insert exams for their subjects\nCREATE POLICY \"Teachers can insert exams\" ON public.exams\n  FOR INSERT WITH CHECK (\n    subject_id IN (\n      SELECT id FROM public.subjects WHERE teacher_id::text = auth.uid()::text\n    )\n  );\n\n-- Exams can be updated by teachers of that subject\nCREATE POLICY \"Teachers can update own exams\" ON public.exams\n  FOR UPDATE USING (\n    subject_id IN (\n      SELECT id FROM public.subjects WHERE teacher_id::text = auth.uid()::text\n    )\n  );\n\n-- Exams can be deleted by teachers of that subject\nCREATE POLICY \"Teachers can delete own exams\" ON public.exams\n  FOR DELETE USING (\n    subject_id IN (\n      SELECT id FROM public.subjects WHERE teacher_id::text = auth.uid()::text\n    )\n  );\n\n-- Results visible to all (teachers for their subjects, parents for their child)\nCREATE POLICY \"Results visible to all\" ON public.results\n  FOR SELECT USING (true);\n\n-- Teachers can insert results for their subjects\nCREATE POLICY \"Teachers can insert results\" ON public.results\n  FOR INSERT WITH CHECK (\n    subject_id IN (\n      SELECT id FROM public.subjects WHERE teacher_id::text = auth.uid()::text\n    )\n  );\n\n-- Announcements visible to all authenticated users\nCREATE POLICY \"Announcements visible to all\" ON public.announcements\n  FOR SELECT USING (auth.role() = 'authenticated');\n\n-- Teachers can insert announcements\nCREATE POLICY \"Teachers can insert announcements\" ON public.announcements\n  FOR INSERT WITH CHECK (author_id::text = auth.uid()::text AND auth.role() = 'authenticated');\n\n-- Teachers can update own announcements\nCREATE POLICY \"Teachers can update own announcements\" ON public.announcements\n  FOR UPDATE USING (author_id::text = auth.uid()::text);\n\n-- Teachers can delete own announcements\nCREATE POLICY \"Teachers can delete own announcements\" ON public.announcements\n  FOR DELETE USING (author_id::text = auth.uid()::text);\n\n-- Chats visible to all authenticated users\nCREATE POLICY \"Chats visible to all\" ON public.chats\n  FOR SELECT USING (auth.role() = 'authenticated');\n\n-- Authenticated users can insert chats\nCREATE POLICY \"Users can insert chats\" ON public.chats\n  FOR INSERT WITH CHECK (sender_id::text = auth.uid()::text AND auth.role() = 'authenticated');\n"